//------------------------------------------Scene s RT--------------------------------------------------

function SceneRT(size:BABYLON.Vector2,scene:BABYLON.Scene):BABYLON.RenderTargetTexture
{

var renderTarget = new BABYLON.RenderTargetTexture("RT_Scene1", {width:size.x,height:size.y}, scene, true);
scene.customRenderTargets.push(renderTarget);
renderTarget.clearColor=new BABYLON.Color4(0,0,0,0)


scene.meshes.forEach(function(mesh) {
    renderTarget.renderList.push(mesh);


    if(!mesh.material){    renderTarget.setMaterialForRendering(mesh, DefaultMaterial1);}
    else{    renderTarget.setMaterialForRendering(mesh, mesh.material);}

});
return renderTarget
}

